const start = Date.now();
const body = $('Validate Input1').first().json.body;

const test_type = body.test_type || '';
const patient   = body.patient_name || 'Невідомий';

// ── Нормалізація відповідей ──────────────────────────────────────────────────
let raw = body.answers || [];
let answers;
if (!Array.isArray(raw) && typeof raw === 'object') {
  answers = Object.keys(raw).sort((a,b)=>parseInt(a)-parseInt(b)).map(k=>parseInt(raw[k])||0);
} else {
  answers = raw.map(a=>parseInt(a)||0);
}

function resolveType(declared, ans) {
  if (['pcl5','minmult','schmishek','phq9','gad7','isi','phq15','pss10','who5','nsi','brief_cope','audit_c','audit','c_ssrs','express'].includes(declared)) return declared;
  if (declared) throw new Error('Unknown test_type: ' + declared);
  if (ans.length <= 20) return 'pcl5';
  if (ans.length <= 71) return 'minmult';
  return 'schmishek';
}
const resolved_type = resolveType(test_type, answers);

// ── Сувора перевірка відповідей: жодних мовчазних підстановок нулів ─────────
// Порожнє, нечислове або недопустиме значення = помилка (токен звільняється, пацієнт отримує 500 і може повторити).
const ALLOWED_VALUES = { pcl5: [0, 1, 2, 3, 4], minmult: [0, 1], schmishek: [0, 1], phq9: [0, 1, 2, 3], gad7: [0, 1, 2, 3],
  isi: [0, 1, 2, 3, 4], phq15: [0, 1, 2], pss10: [0, 1, 2, 3, 4], who5: [0, 1, 2, 3, 4, 5], nsi: [0, 1, 2, 3, 4], brief_cope: [0, 1, 2, 3], audit_c: [0, 1, 2, 3, 4], audit: [0, 1, 2, 3, 4], c_ssrs: [0, 1, 2], express: [0, 1, 2, 3, 4] };
const rawList = Array.isArray(raw)
  ? raw
  : Object.keys(raw).sort((a, b) => parseInt(a) - parseInt(b)).map(k => raw[k]);
const isValidAnswer = (v) =>
  (typeof v === 'number' || (typeof v === 'string' && /^\d+$/.test(v))) &&
  ALLOWED_VALUES[resolved_type].includes(Number(v));
if (!rawList.every(isValidAnswer)) {
  throw new Error('Invalid answer value for ' + resolved_type + ' (empty, non-numeric or out of range)');
}

// ── PCL-5 (20 питань, шкала 0-4) ────────────────────────────────────────────
// Кластери DSM-5:
// B (1-5)  — Вторгнення
// C (6-7)  — Уникнення
// D (8-14) — Негативні зміни когніцій/настрою
// E (15-20)— Гіперзбудження
function score_pcl5(ans) {
  if (ans.length !== 20) throw new Error('PCL-5: expected 20 answers, got ' + ans.length);
  const a = ans.map(v => Math.min(4, Math.max(0, v)));
  const sum = (arr) => arr.reduce((s, v) => s + v, 0);
  const pos = (arr) => arr.filter(v => v >= 2).length;
  const cl = { B: a.slice(0,5), C: a.slice(5,7), D: a.slice(7,14), E: a.slice(14,20) };
  const clusters = { B: sum(cl.B), C: sum(cl.C), D: sum(cl.D), E: sum(cl.E) };
  const total = sum(a);
  // DSM-5 provisional: >=1 B, >=1 C, >=2 D, >=2 E при оцінці >=2 (правило за пам'яттю, не перевірено)
  const dsm_provisional = pos(cl.B)>=1 && pos(cl.C)>=1 && pos(cl.D)>=2 && pos(cl.E)>=2;
  const cutoff_met = total >= 33; // діапазон порога 31–33 (не перевірено)
  return {
    total,
    severity: 'pending',
    severity_ua: `Сума ${total}/80; поріг 31–33: ${cutoff_met ? 'досягнуто' : 'не досягнуто'}; DSM-5 (попередньо): ${dsm_provisional ? 'так' : 'ні'}`,
    ptsd_probable: dsm_provisional || cutoff_met,
    details: { clusters, dsm_provisional, cutoff_met },
    subscales: {
      'B_Вторгнення': clusters.B, 'C_Уникнення': clusters.C,
      'D_Когніції/настрій': clusters.D, 'E_Збудження': clusters.E,
    },
  };
}

// ── Міні-Мульт (Kincannon 1968; Зайцев 1981) — 71 питання, відповіді Так(1)/Ні(0) ──
// УВАГА: ключ взято з методички (gosuslugi PDF), НЕ верифіковано за Козюля В.Г. (1994).
// Відомі підозрілі місця: шкала D (номер 11 і в "Ні", і в "Так"), шкала F.
// Нумерація питань має збігатися з версією тексту, до якої складено ключ (пп. 26-27 розходяться між джерелами).
// Т-бали потребують профільних листів (Козюля) — тут не розраховуються.
const MM_KEY = {
  L:  { no: [5,11,24,47,53], yes: [] },
  F:  { no: [22,24,61], yes: [9,12,15,19,30,38,48,49,58,59,64,71] },
  K:  { no: [11,23,31,33,34,36,40,41,43,51,56,61,65,67,69,70], yes: [] },
  'Hs_1_Іпохондрія':   { no: [1,2,6,37,45], yes: [9,18,26,32,44,46,55,62,63] },
  'D_2_Депресія':      { no: [1,3,6,11,28,37,40,42,60,65,71], yes: [9,13,17,18,22,25,36,44] },
  'Hy_3_Істерія':      { no: [1,2,3,11,23,28,29,31,33,35,37,40,41,43,45,50,56], yes: [9,13,18,26,44,46,55,57,62] },
  'Pd_4_Психопатія':   { no: [3,28,34,35,41,43,50,65], yes: [7,10,13,14,15,16,22,27,52,58,71] },
  'Pa_6_Параноя':      { no: [28,29,31,67], yes: [5,8,10,15,30,39,63,64,66,68] },
  'Pt_7_Психастенія':  { no: [2,3,42], yes: [5,8,13,17,22,25,27,36,44,51,57,66,68] },
  'Sc_8_Шизоїдність':  { no: [3,42], yes: [5,7,8,10,13,14,15,16,17,26,30,38,39,46,57,63,64,66] },
  'Ma_9_Гіпоманія':    { no: [43], yes: [4,7,8,21,29,34,38,39,54,57,60] },
};
// Поправка на K: частка K, що додається до шкали
const MM_K_COEF = { 'Hs_1_Іпохондрія': 0.5, 'Pd_4_Психопатія': 0.4, 'Pt_7_Психастенія': 1.0, 'Sc_8_Шизоїдність': 1.0, 'Ma_9_Гіпоманія': 0.2 };

// Pd: поправка 0,4К берётся из таблицы источника (Math.round расходится с ней при K=1 и K=3)
const MM_PD_TABLE = {0:0,1:1,2:1,3:2,4:2,5:2,6:2,7:3,8:3,9:4,10:4,11:4,12:5,13:5,14:6,15:6,16:6};
function mm_k_add(n, K) {
  if (n === 'Pd_4_Психопатія' && MM_PD_TABLE[K] !== undefined) return MM_PD_TABLE[K];
  return Math.round((MM_K_COEF[n] || 0) * K);
}

// ── T-бали (T = 50 + 10·(X − M)/σ), норми за статтю з таблиці джерела ──────────
// Х для Hs, Pd, Pt, Sc, Ma — бал уже з поправкою на K; L, F, K — сирі.
const MM_NORMS = {
  M: { L:[1.48,1.23], F:[3.1,2.3], K:[7.68,3.42],
       'Hs_1_Іпохондрія':[7.24,3], 'D_2_Депресія':[7.02,2.68], 'Hy_3_Істерія':[9.73,2.91],
       'Pd_4_Психопатія':[10.39,2.13], 'Pa_6_Параноя':[4.03,1.74], 'Pt_7_Психастенія':[13.57,2.51],
       'Sc_8_Шизоїдність':[13.68,2.83], 'Ma_9_Гіпоманія':[6.23,1.55] },
  F: { L:[1.51,1.19], F:[2.64,1.71], K:[7.72,2.64],
       'Hs_1_Іпохондрія':[8.47,2.92], 'D_2_Депресія':[7.96,3], 'Hy_3_Істерія':[11.53,3.38],
       'Pd_4_Психопатія':[9.76,1.9], 'Pa_6_Параноя':[4.77,2], 'Pt_7_Психастенія':[14.48,2.27],
       'Sc_8_Шизоїдність':[13.52,2.8], 'Ma_9_Гіпоманія':[6.35,1.91] },
};
function mm_t(sex, name, x) {
  const t = MM_NORMS[sex] && MM_NORMS[sex][name];
  return t ? Math.round(50 + 10 * (x - t[0]) / t[1]) : null;
}
const session_sex = (() => {
  try {
    const s = String($('DB: Check Session Status1').first().json.sex || '').trim().toUpperCase();
    return (s === 'M' || s === 'F') ? s : null;
  } catch (e) { return null; }
})();

function score_minmult(ans, sex) {
  if (ans.length !== 71) throw new Error('Mini-Mult: expected 71 answers, got ' + ans.length);
  const a = ans.slice(0, 71);
  const raw = {};
  for (const [name, key] of Object.entries(MM_KEY)) {
    let s = 0;
    for (const k of key.yes) if (k <= a.length && a[k-1] === 1) s++;
    for (const k of key.no)  if (k <= a.length && a[k-1] === 0) s++;
    raw[name] = s;
  }
  const K = raw.K;
  const clinical = Object.keys(MM_KEY).filter(n => !['L','F','K'].includes(n));
  const scales = {};
  const scales_raw = {};
  for (const n of clinical) { scales_raw[n] = raw[n]; scales[n] = raw[n] + mm_k_add(n, K); }
  const values = clinical.map(n => scales[n]);
  const maxVal = Math.max(...values);
  const total = values.reduce((s,v) => s+v, 0);
  const peak_scale = clinical[values.indexOf(maxVal)];
  const validity = { L: raw.L, F: raw.F, K };
  let t_scores = null, t_validity = null;
  if (sex) {
    t_scores = {}; for (const n of clinical) t_scores[n] = mm_t(sex, n, scales[n]);
    t_validity = { L: mm_t(sex, 'L', raw.L), F: mm_t(sex, 'F', raw.F), K: mm_t(sex, 'K', raw.K) };
  }
  return {
    total,
    severity: 'unknown',
    severity_ua: 'Т-бали не розраховано (див. шкали)',
    peak_scale,
    subscales: scales,
    validity,
    elevated_scales: [],
    details: { subscales: scales, subscales_raw: scales_raw, validity, peak_scale, k_corrected: true, sex: sex || null, ...(t_scores ? { t_scores, t_validity, t_formula: 'T = 50 + 10*(X - M)/sigma' } : {}) }
  };
}

// ── Шмішек — 88 питань, відповіді Так(1)/Ні(0), 10 шкал (Леонгард) ──────────────
// Ключ і множники: стандартний ключ опитувальника (методичка gosuslugi PDF). Макс. на шкалу = 24.
const SCH_KEY = {
  'Демонстративність': { yes: [7,19,22,29,41,44,63,66,73,85,88], no: [51], mult: 2 },
  'Застрягання':       { yes: [2,15,24,34,37,56,68,78,81],       no: [12,46,59], mult: 2 },
  'Педантизм':         { yes: [4,14,17,26,36,48,58,61,70,80,83], no: [39], mult: 2 },
  'Збудливість':       { yes: [8,20,30,42,52,64,74,86],          no: [], mult: 3 },
  'Гіпертимія':        { yes: [1,11,23,33,45,55,67,77],          no: [], mult: 3 },
  'Дистимія':          { yes: [9,21,43,75,87],                   no: [31,53,65], mult: 3 },
  'Тривожність':       { yes: [16,27,38,49,60,71,82],            no: [5], mult: 3 },
  'Екзальтованість':   { yes: [10,32,54,76],                     no: [], mult: 6 },
  'Емотивність':       { yes: [3,13,35,47,57,69,79],             no: [25], mult: 3 },
  'Циклотимія':        { yes: [6,18,28,40,50,62,72,84],          no: [], mult: 3 },
};
// Джерела розходяться: ознака акцентуації >12 або >19 (15-19 = тенденція). Змінюйте тут.
const SCH_ACCENT_MIN = 20;
// Джерело: 15–19 балів — лише тенденція до акцентуації, >19 — акцентуація
const SCH_TENDENCY_MIN = 15;

function score_schmishek(ans) {
  if (ans.length !== 88) throw new Error('Schmishek: expected 88 answers, got ' + ans.length);
  const a = ans.slice(0, 88);
  const scales = {};
  for (const [name, key] of Object.entries(SCH_KEY)) {
    let s = 0;
    for (const k of key.yes) if (k <= a.length && a[k-1] === 1) s++;
    for (const k of key.no)  if (k <= a.length && a[k-1] === 0) s++;
    scales[name] = s * key.mult;
  }
  const entries = Object.entries(scales);
  const peak = [...entries].sort(([,x],[,y]) => y - x)[0];
  const total = entries.reduce((s,[,v]) => s+v, 0);
  const accentuated = entries.filter(([,v]) => v >= SCH_ACCENT_MIN).map(([k]) => k);

  let severity, severity_ua;
  if (accentuated.length === 0)     { severity='low';      severity_ua='В нормі'; }
  else if (accentuated.length <= 2) { severity='moderate'; severity_ua='Акцентуація'; }
  else if (accentuated.length <= 4) { severity='high';     severity_ua='Виражена'; }
  else                              { severity='severe';   severity_ua='Дуже виражена'; }

  const profile = Object.keys(SCH_KEY).map(name => ({
    name,
    score: scales[name],
    level: scales[name] >= SCH_ACCENT_MIN ? 'accentuation' : (scales[name] >= SCH_TENDENCY_MIN ? 'tendency' : 'normal')
  }));
  const tendency = profile.filter(p => p.level === 'tendency').map(p => p.name);
  return {
    total, severity, severity_ua,
    subscales: Object.fromEntries([...entries].sort(([,x],[,y]) => y - x)),
    accentuated_types: accentuated,
    peak_type: peak?.[0],
    peak_score: peak?.[1],
    details: { profile, accentuated_types: accentuated, tendency_types: tendency, thresholds: { accentuation: SCH_ACCENT_MIN, tendency: SCH_TENDENCY_MIN }, max_per_scale: 24 }
  };
}

// ── PHQ-9 (9 питань 0-3 + опціональне 10-те функціональне 0-3) ──────────────
// Пороги: 0-4 мінімальні, 5-9 легкі, 10-14 помірні, 15-19 помірно тяжкі, 20-27 тяжкі.
// Пункт 9 (суїцидальні думки) > 0 => item9_positive незалежно від суми.
const PHQ9_FUNC = ['Зовсім не складно', 'Дещо складно', 'Дуже складно', 'Надзвичайно складно'];
const PHQ9_SEV = [
  [4,  'minimal',           'Мінімальні або відсутні симптоми'],
  [9,  'mild',              'Легкий рівень симптомів'],
  [14, 'moderate',          'Помірний рівень симптомів'],
  [19, 'moderately_severe', 'Помірно тяжкий рівень симптомів'],
  [27, 'severe',            'Тяжкий рівень симптомів'],
];
function score_phq9(ans) {
  if (ans.length !== 9 && ans.length !== 10) throw new Error('PHQ-9: expected 9 or 10 answers, got ' + ans.length);
  const total = ans.slice(0, 9).reduce((s, v) => s + v, 0);
  const [, severity, label] = PHQ9_SEV.find(([lim]) => total <= lim);
  const item9_positive = ans[8] > 0;
  const functional = ans.length === 10 ? PHQ9_FUNC[ans[9]] : 'не вказано';
  return {
    total,
    severity,
    severity_ua: `Сума ${total}/27: ${label}${item9_positive ? '; ПУНКТ 9 ПОЗИТИВНИЙ (думки про смерть/самопошкодження)' : ''}`,
    item9_positive,
    subscales: { 'PHQ9_Сума': total, 'Пункт9_суїцидальні_думки': ans[8] },
    details: { item9_positive, item9_value: ans[8], functional_difficulty: functional, severity_label: label },
  };
}

// ── GAD-7 (7 питань 0-3 + опціональне 8-те функціональне 0-3) ───────────────
// Пороги: 0-4 мінімальна, 5-9 легка, 10-14 помірна, 15-21 тяжка тривога.
// Поріг >=10 — стандартна точка відсічення для вірогідного GAD (Spitzer 2006; за пам'яттю, не перевірено).
const GAD7_FUNC = ['Зовсім не складно', 'Дещо складно', 'Дуже складно', 'Надзвичайно складно'];
const GAD7_SEV = [
  [4,  'minimal',  'Мінімальна тривога'],
  [9,  'mild',     'Легка тривога'],
  [14, 'moderate', 'Помірна тривога'],
  [21, 'severe',   'Тяжка тривога'],
];
function score_gad7(ans) {
  if (ans.length !== 7 && ans.length !== 8) throw new Error('GAD-7: expected 7 or 8 answers, got ' + ans.length);
  const total = ans.slice(0, 7).reduce((s, v) => s + v, 0);
  const [, severity, label] = GAD7_SEV.find(([lim]) => total <= lim);
  const cutoff_met = total >= 10;
  const functional = ans.length === 8 ? GAD7_FUNC[ans[7]] : 'не вказано';
  return {
    total,
    severity,
    severity_ua: `Сума ${total}/21: ${label}; поріг ≥10: ${cutoff_met ? 'досягнуто' : 'не досягнуто'}`,
    subscales: { 'GAD7_Сума': total },
    details: { cutoff_met, cutoff_value: 10, functional_difficulty: functional, severity_label: label },
  };
}


// ══ ЕТАП 1: нові шкали Лікерта ══════════════════════════════════════════════
function sev_pick(table, total) { return table.find(([lim]) => total <= lim); }
const sum_ = (arr) => arr.reduce((s, v) => s + v, 0);

// ── ISI (Morin, 7 пунктів 0-4; 0-28) ─────────────────────────────────────────
const ISI_SEV = [
  [7,  'none',         'Клінічно значущої безсоння немає'],
  [14, 'subthreshold', 'Субпорогова безсоння'],
  [21, 'moderate',     'Клінічна безсоння помірної тяжкості'],
  [28, 'severe',       'Клінічна безсоння тяжкого ступеня'],
];
function score_isi(ans) {
  if (ans.length !== 7) throw new Error('ISI: expected 7 answers, got ' + ans.length);
  const total = sum_(ans);
  const [, severity, label] = sev_pick(ISI_SEV, total);
  return { total, severity, severity_ua: `Сума ${total}/28: ${label}`,
    subscales: { 'ISI_Сума': total }, details: { severity_label: label, cutoff_met: total >= 15, cutoff_value: 15 } };
}

// ── PHQ-15 (15 пунктів 0-2; 0-30; пороги 5/10/15) ────────────────────────────
const PHQ15_SEV = [
  [4,  'minimal', 'Мінімальна соматизація'],
  [9,  'low',     'Низький рівень соматичних симптомів'],
  [14, 'medium',  'Середній рівень соматичних симптомів'],
  [30, 'high',    'Високий рівень соматичних симптомів'],
];
function score_phq15(ans) {
  if (ans.length !== 15) throw new Error('PHQ-15: expected 15 answers, got ' + ans.length);
  const total = sum_(ans);
  const [, severity, label] = sev_pick(PHQ15_SEV, total);
  return { total, severity, severity_ua: `Сума ${total}/30: ${label}`,
    subscales: { 'PHQ15_Сума': total }, details: { severity_label: label, cutoff_met: total >= 10, cutoff_value: 10 } };
}

// ── PSS-10 (10 пунктів 0-4; зворотні 4,5,7,8; 0-40) ──────────────────────────
// Офіційних клінічних порогів у Cohen немає; 0-13/14-26/27-40 — умовний поділ з літератури (не верифіковано).
const PSS10_REV = [3, 4, 6, 7]; // індекси пунктів 4,5,7,8
const PSS10_SEV = [
  [13, 'low',      'Низький рівень сприйнятого стресу'],
  [26, 'moderate', 'Помірний рівень сприйнятого стресу'],
  [40, 'high',     'Високий рівень сприйнятого стресу'],
];
function score_pss10(ans) {
  if (ans.length !== 10) throw new Error('PSS-10: expected 10 answers, got ' + ans.length);
  const a = ans.map((v, i) => PSS10_REV.includes(i) ? 4 - v : v);
  const total = sum_(a);
  const [, severity, label] = sev_pick(PSS10_SEV, total);
  return { total, severity, severity_ua: `Сума ${total}/40: ${label} (умовні межі)`,
    subscales: { 'PSS10_Сума': total },
    details: { severity_label: label, reversed_items: [4, 5, 7, 8], scored_items: a } };
}

// ── WHO-5 (5 пунктів 0-5; сирий 0-25 ×4 = 0-100) ─────────────────────────────
// ≤50 — низьке благополуччя, ≤28 — ймовірна депресія (Topp 2015; за пам'яттю, не перевірено).
function score_who5(ans) {
  if (ans.length !== 5) throw new Error('WHO-5: expected 5 answers, got ' + ans.length);
  const raw = sum_(ans);
  const total = raw * 4;
  const severity = total <= 28 ? 'very_low' : total <= 50 ? 'low' : 'ok';
  const label = { very_low: 'Дуже низьке благополуччя (рекомендовано скринінг депресії)',
                  low: 'Знижене благополуччя', ok: 'Благополуччя в межах норми' }[severity];
  return { total, severity, severity_ua: `Індекс ${total}/100: ${label}`,
    subscales: { 'WHO5_Індекс': total, 'WHO5_Сирий': raw },
    details: { severity_label: label, raw, cutoff_met: total <= 50, cutoff_value: 50 } };
}

// ── NSI (22 пункти 0-4; 0-88). Клінічних порогів немає — лише сума й умовні групи ─
const NSI_GROUPS = { 'Фізичні_1-12': [0, 12], 'Когнітивні_13-16': [12, 16], 'Сон_втома_17-18': [16, 18], 'Емоційні_19-22': [18, 22] };
function score_nsi(ans) {
  if (ans.length !== 22) throw new Error('NSI: expected 22 answers, got ' + ans.length);
  const total = sum_(ans);
  const subscales = { 'NSI_Сума': total };
  for (const [k, [a, b]] of Object.entries(NSI_GROUPS)) subscales['NSI_' + k] = sum_(ans.slice(a, b));
  return { total, severity: 'pending', severity_ua: `Сума ${total}/88 (порогів немає, оцінює фахівець)`,
    subscales, details: { groups_note: 'умовне групування, не валідована факторна структура' } };
}


// ══ ЕТАП 2: Brief COPE (Carver 1997; 28 пунктів 0-3; 14 підшкал по 2 пункти, 0-6) ══
// Клінічних порогів і загального балу немає; score = сума всіх пунктів лише для зберігання.
const COPE_SUBS = {
  'Відволікання':            [1, 19],
  'Активне_подолання':       [2, 7],
  'Заперечення':             [3, 8],
  'Вживання_речовин':        [4, 11],
  'Емоційна_підтримка':      [5, 15],
  'Інструментальна_підтримка': [10, 23],
  'Поведінкове_відсторонення': [6, 16],
  'Вираження_емоцій':        [9, 21],
  'Позитивне_переосмислення': [12, 17],
  'Планування':              [14, 25],
  'Гумор':                   [18, 28],
  'Прийняття':               [20, 24],
  'Релігія':                 [22, 27],
  'Самозвинувачення':        [13, 26],
};
function score_brief_cope(ans) {
  if (ans.length !== 28) throw new Error('Brief COPE: expected 28 answers, got ' + ans.length);
  const subs = {};
  for (const [k, [i, j]] of Object.entries(COPE_SUBS)) subs[k] = ans[i - 1] + ans[j - 1];
  const grp = (items) => { const s = sum_(items.map(i => ans[i - 1])); return { sum: s, max: items.length * 3, mean: Math.round(s / items.length * 100) / 100 }; };
  const macro = {
    'Проблемно-орієнтований': grp([2, 7, 10, 12, 14, 17, 23, 25]),
    'Емоційно-орієнтований':  grp([5, 9, 13, 15, 18, 20, 21, 22, 24, 26, 27, 28]),
    'Уникаючий':              grp([1, 3, 4, 6, 8, 11, 16, 19]),
  };
  const substance_flag = subs['Вживання_речовин'] >= 3;
  const total = sum_(ans);
  // top3: при рівних балах не обрізати за порядком визначення
  const fmt = ([k, v]) => `${k.replace(/_/g, ' ')} (${v})`;
  const sorted = Object.entries(subs).sort((a, b) => b[1] - a[1]);
  let top;
  if (sorted[0][1] === sorted[sorted.length - 1][1]) {
    top = [`профіль рівномірний (усі підшкали = ${sorted[0][1]})`];
  } else {
    const thr = sorted[2][1];
    const above = sorted.filter(e => e[1] > thr);
    const tied = sorted.filter(e => e[1] === thr);
    top = (above.length + tied.length <= 5)
      ? [...above, ...tied].map(fmt)
      : [...above.map(fmt), ...(thr > 0 ? [`ще ${tied.length} підшкал з балом ${thr}`] : [])];
  }
  return { total, severity: 'pending',
    severity_ua: `Профіль копінгу (14 підшкал 0-6). Найвиразніші: ${top.join(', ')}`,
    subscales: subs,
    details: { subscales: subs, top3: top, macro, substance_flag,
      note: 'сума підшкал; порогів немає, оцінює фахівець; макрогрупи — умовне групування, не верифіковано' } };
}


// ══ ЕТАП 3а: AUDIT-C (3 пункти, 0-12) та AUDIT (10 пунктів, 0-40) ═══════════
// AUDIT-C: умовні пороги ≥4 (чоловіки) / ≥3 (жінки); стать у скорер не передається, тому подано обидва прапорці.
// AUDIT: зони 0-7 / 8-15 / 16-19 / 20+ (WHO; за пам'яттю, не перевірено). Пункти 9-10 мають значення 0, 2, 4.
function score_audit_c(ans, sex) {
  if (ans.length !== 3) throw new Error('AUDIT-C: expected 3 answers, got ' + ans.length);
  const total = sum_(ans);
  const men = total >= 4, women = total >= 3;
  const cut = sex === 'F' ? 3 : 4;
  const severity = total >= cut ? 'positive' : (!sex && women) ? 'borderline' : 'negative';
  const label = { positive: `Позитивний скринінг (≥${cut})`,
                  borderline: 'Стать не вказана: позитивний для жінок (≥3), для чоловіків нижче порога',
                  negative: `Негативний скринінг (<${sex ? cut : 3})` }[severity];
  return { total, severity, severity_ua: `Сума ${total}/12: ${label}`,
    subscales: { 'AUDITC_Сума': total },
    details: { severity_label: label, cutoff_men_met: men, cutoff_women_met: women, cutoff_men: 4, cutoff_women: 3, sex_used: sex || null } };
}
const AUDIT_SEV = [
  [7,  'low_risk',   'Низький ризик'],
  [15, 'hazardous',  'Ризиковане вживання'],
  [19, 'harmful',    'Шкідливе вживання'],
  [40, 'dependence', 'Імовірна залежність (потрібна оцінка фахівця)'],
];
function score_audit(ans) {
  if (ans.length !== 10) throw new Error('AUDIT: expected 10 answers, got ' + ans.length);
  if (![0, 2, 4].includes(ans[8]) || ![0, 2, 4].includes(ans[9])) throw new Error('AUDIT: items 9-10 must be 0, 2 or 4');
  const total = sum_(ans);
  const [, severity, label] = sev_pick(AUDIT_SEV, total);
  const part_c = sum_(ans.slice(0, 3));
  return { total, severity, severity_ua: `Сума ${total}/40: ${label}`,
    subscales: { 'AUDIT_Сума': total, 'AUDIT_C_частина_1-3': part_c, 'AUDIT_Залежність_4-6': sum_(ans.slice(3, 6)), 'AUDIT_Шкода_7-10': sum_(ans.slice(6, 10)) },
    details: { severity_label: label, audit_c_part: part_c, injury_item9: ans[8], concern_item10: ans[9] } };
}


// ══ ЕТАП 3б: C-SSRS Screener (6 пунктів) ═══════════════════════════════════════
// П.1-5: 0 = Ні, 1 = Так. П.6: 0 = Ні, 1 = Так (понад 3 міс. тому), 2 = Так (протягом останніх 3 міс.).
// П.2 = Ні -> пп.3-5 не ставляться (автоматично 0). Рівень за тріажем скринера (за пам'яттю, не перевірено):
// високий: пп.4/5 або п.6 за 3 міс.; помірний: п.3 або п.6 раніше; низький: пп.1/2; інакше немає.
function score_c_ssrs(ans) {
  if (ans.length !== 6) throw new Error('C-SSRS: expected 6 answers, got ' + ans.length);
  if (ans.slice(0, 5).some(v => v > 1)) throw new Error('C-SSRS: items 1-5 must be 0 or 1');
  if (ans[1] === 0 && (ans[2] || ans[3] || ans[4])) throw new Error('C-SSRS: items 3-5 must be 0 when item 2 is No');
  const level = (ans[3] || ans[4] || ans[5] === 2) ? 3 : (ans[2] || ans[5] === 1) ? 2 : (ans[0] || ans[1]) ? 1 : 0;
  const severity = ['none', 'low', 'moderate', 'high'][level];
  const label = ['Ознак ризику не виявлено', 'Низький ризик (пп. 1-2)', 'Помірний ризик (п. 3 або минула поведінка)',
                 'ВИСОКИЙ ризик (наміри/план або поведінка за останні 3 міс.)'][level];
  const yes_items = ans.map((v, i) => v > 0 ? i + 1 : null).filter(x => x);
  return { total: level, severity, severity_ua: label,
    subscales: {}, 
    details: { severity_label: label, risk_level: level, yes_items, q6_recent: ans[5] === 2 } };
}

// ── Запуск ───────────────────────────────────────────────────────────────────
// ══ ЕТАП 4: Комплексний експрес-скринінг = PHQ-9 (1-9) + GAD-7 (10-16) + ISI (17-23) + AUDIT-C (24-26) ═══
// Загального балу немає: кожна шкала оцінюється окремо існуючими скорерами.
// score (results.score) = кількість шкал на рівні >= 2 (0-4); severity = найвищий рівень серед шкал.
// Рівні 0-3: PHQ-9 <5/5/10/20, GAD-7 <5/5/10/15, ISI <8/8/15/22; AUDIT-C 0 негативний, 1 прикордонний (стать не вказана), 2 позитивний.
function score_express(ans, sex) {
  if (ans.length !== 26) throw new Error('Express: expected 26 answers, got ' + ans.length);
  const parts = [ans.slice(0, 9), ans.slice(9, 16), ans.slice(16, 23), ans.slice(23, 26)];
  if (parts[0].some(v => v > 3) || parts[1].some(v => v > 3)) throw new Error('Express: PHQ-9/GAD-7 values must be 0-3');
  const p = score_phq9(parts[0]), g = score_gad7(parts[1]), i = score_isi(parts[2]), a = score_audit_c(parts[3], sex);
  const lv = [
    p.total >= 20 ? 3 : p.total >= 10 ? 2 : p.total >= 5 ? 1 : 0,
    g.total >= 15 ? 3 : g.total >= 10 ? 2 : g.total >= 5 ? 1 : 0,
    i.total >= 22 ? 3 : i.total >= 15 ? 2 : i.total >= 8 ? 1 : 0,
    a.severity === 'positive' ? 2 : a.severity === 'borderline' ? 1 : 0,
  ];
  const scales = [
    { key: 'phq9',    name: 'PHQ-9 (депресія)',  score: p.total, max: 27, level: lv[0], level_ua: p.details.severity_label },
    { key: 'gad7',    name: 'GAD-7 (тривога)',   score: g.total, max: 21, level: lv[1], level_ua: g.details.severity_label },
    { key: 'isi',     name: 'ISI (порушення сну)', score: i.total, max: 28, level: lv[2], level_ua: i.details.severity_label },
    { key: 'audit_c', name: 'AUDIT-C (алкоголь)', score: a.total, max: 12, level: lv[3], level_ua: a.details.severity_label },
  ].map(s => ({ ...s, flag: s.level >= 2 }));
  const worst = Math.max(...lv);
  const severity = ['none', 'attention', 'elevated', 'high'][worst];
  const item9_positive = p.item9_positive;
  const summary = scales.map(s => `${s.name.split(' ')[0]} ${s.score}/${s.max}`).join('; ');
  return { total: scales.filter(s => s.flag).length, severity,
    severity_ua: `Зведення: ${summary}${item9_positive ? '; ПУНКТ 9 PHQ-9 ПОЗИТИВНИЙ' : ''}`,
    item9_positive,
    subscales: { 'PHQ9_Сума': p.total, 'GAD7_Сума': g.total, 'ISI_Сума': i.total, 'AUDITC_Сума': a.total, 'Пункт9_суїцидальні_думки': parts[0][8] },
    details: { scales, item9_positive, item9_value: parts[0][8], worst_level: worst, sex_used: sex || null } };
}

const scorers    = { pcl5: score_pcl5, minmult: score_minmult, schmishek: score_schmishek, phq9: score_phq9, gad7: score_gad7,
  isi: score_isi, phq15: score_phq15, pss10: score_pss10, who5: score_who5, nsi: score_nsi, brief_cope: score_brief_cope, audit_c: score_audit_c, audit: score_audit, c_ssrs: score_c_ssrs, express: score_express };
const test_names = { pcl5:'PCL-5 (ПТСР)', minmult:'Міні-Мульт (MMPI)', schmishek:'Шмішек (акцентуації)', phq9:'PHQ-9 (депресія)', gad7:'GAD-7 (тривога)',
  isi:'ISI (порушення сну)', phq15:'PHQ-15 (соматизація)', pss10:'PSS-10 (рівень стресу)', who5:'WHO-5 (індекс благополуччя)', nsi:'NSI (посткомоційний синдром)', brief_cope:'Brief COPE (копінг-стратегії)', audit_c:'AUDIT-C (скринінг алкоголю)', audit:'AUDIT (вживання алкоголю)', c_ssrs:'C-SSRS (суїцидальний ризик)', express:'Комплексний експрес-скринінг' };

if (!scorers[resolved_type]) throw new Error('Unknown test_type: ' + resolved_type);

const result = scorers[resolved_type](answers, session_sex);
const scoring_time_ms = Date.now() - start;

return [{
  json: {
    ...body,
    answers,
    test_type:        resolved_type,
    test_name:        test_names[resolved_type],
    score:            result.total,
    severity:         result.severity,
    severity_ua:      result.severity_ua,
    subscales:        result.subscales,
    scoring_time_ms,
    // Поля специфічні для кожного тесту
    ...(result.ptsd_probable     !== undefined && { ptsd_probable:     result.ptsd_probable }),
    ...(result.item9_positive    !== undefined && { item9_positive:    result.item9_positive }),
    crisis_level: resolved_type === 'c_ssrs'
      ? ['none', 'attention', 'elevated', 'high'][result.total]
      : (result.item9_positive ? 'attention' : 'none'),
    ...(result.peak_scale        !== undefined && { peak_scale:        result.peak_scale }),
    ...(result.elevated_scales   !== undefined && { elevated_scales:   result.elevated_scales }),
    ...(result.validity          !== undefined && { validity:          result.validity }),
    ...(result.accentuated_types !== undefined && { accentuated_types: result.accentuated_types }),
    ...(result.peak_type         !== undefined && { peak_type:         result.peak_type }),
    ...(result.peak_score        !== undefined && { peak_score:        result.peak_score }),
    details:           { ...(result.details || {}), sex: session_sex },
  }
}];
